def generate_xlsx(output_path):
    wb = Workbook()
    # TestPlan sheet
    ws_tp = wb.active
    ws_tp.title = 'TestPlan'
    tp_cols = ['Index', 'SS / Module', 'Feature', 'Test Case Name', 'Test Description',
               'Speed', 'Mode', 'Memory Start Offset', 'Memory End Offset', 'Remarks',
               'Test Steps / Procedure', 'Impacted Registers', 'Validation / Acceptance Criteria',
               'Code Generation']
    # MetaData sheet
    ws_md = wb.create_sheet('MetaData')
    md_cols = ['Index', 'Test Case Name', 'Meta Test Description', 'Meta Test Steps / Procedure',
               'Meta Impacted Registers', 'Meta Validation / Acceptance Criteria',
               'Meta Headers', 'Meta Macros', 'Meta Arrays']
    header_font = Font(bold=True, color='FFFFFF', size=11)
    header_fill = PatternFill(start_color='4472C4', end_color='4472C4', fill_type='solid')
    wrap = Alignment(wrap_text=True, vertical='top')
    for sheet, cols in [(ws_tp, tp_cols), (ws_md, md_cols)]:
        for ci, col_name in enumerate(cols, 1):
            cell = sheet.cell(row=1, column=ci, value=col_name)
            cell.font = header_font
            cell.fill = header_fill
            cell.alignment = wrap
        sheet.freeze_panes = 'A2'
    for ri, row in enumerate(json_data, 2):
        for ci, col in enumerate(tp_cols, 1):
            val = row.get(col, '')
            cell = ws_tp.cell(row=ri, column=ci, value=val)
            cell.alignment = wrap
        for ci, col in enumerate(md_cols, 1):
            val = row.get(col, '')
            cell = ws_md.cell(row=ri, column=ci, value=val)
            cell.alignment = wrap
    for sheet, cols in [(ws_tp, tp_cols), (ws_md, md_cols)]:
        for ci in range(1, len(cols)+1):
            max_len = len(str(sheet.cell(row=1, column=ci).value))
            for ri in range(2, len(json_data)+2):
                cv = str(sheet.cell(row=ri, column=ci).value or '')
                lines = cv.split('\n')
                for line in lines:
                    max_len = max(max_len, len(line))
            width = min(max_len + 4, 80)
            sheet.column_dimensions[get_column_letter(ci)].width = width
    ws_md.sheet_state = 'veryHidden'
    wb.save(output_path)
    print(f'Workbook saved: {output_path}')
    print(f'File size: {os.path.getsize(output_path)} bytes')
    vwb = load_workbook(output_path)
    print(f'Sheets: {vwb.sheetnames}')
    print(f'TestPlan rows: {vwb["TestPlan"].max_row - 1}')
    print(f'MetaData rows: {vwb["MetaData"].max_row - 1}')
    print('Validation: PASSED')
    return output_path

if __name__ == '__main__':
    script_dir = os.path.dirname(os.path.abspath(__file__))
    out = os.path.join(script_dir, 'PCIE_TestPlan_20260903_112434.xlsx')
    generate_xlsx(out)
